SELECT org, nb, CASE WHEN selfb > 0 THEN 1 ELSE 0 END AS label_is_buyer, count(*) AS notices FROM (SELECT q.org AS org, q.tid AS tid, q.nid AS nid, count(DISTINCT b.mention_section_id) AS nb, sum(CASE WHEN b.organization_id = q.org THEN 1 ELSE 0 END) AS selfb FROM (SELECT DISTINCT 1164742 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1164742 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.mention_notice_id = q.nid AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid UNION ALL SELECT q.org AS org, q.tid AS tid, q.nid AS nid, count(DISTINCT b.mention_section_id) AS nb, sum(CASE WHEN b.organization_id = q.org THEN 1 ELSE 0 END) AS selfb FROM (SELECT DISTINCT 1171563 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1171563 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.mention_notice_id = q.nid AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid UNION ALL SELECT q.org AS org, q.tid AS tid, q.nid AS nid, count(DISTINCT b.mention_section_id) AS nb, sum(CASE WHEN b.organization_id = q.org THEN 1 ELSE 0 END) AS selfb FROM (SELECT DISTINCT 1166638 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1166638 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.mention_notice_id = q.nid AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid UNION ALL SELECT q.org AS org, q.tid AS tid, q.nid AS nid, count(DISTINCT b.mention_section_id) AS nb, sum(CASE WHEN b.organizati